"""Share of the total dose per sample."""
from samples import load_samples


def dose_shares(samples):
    """Return each sample's share of the total dose, in order."""
    total = sum(x.dose for x in samples)
    return [x.dose / total for x in samples]


def stored_shares():
    """Shares for the stored samples."""
    return dose_shares(load_samples())


def top_share(samples):
    """Return the largest share, or 0.0 when there are no samples."""
    shares = dose_shares(samples)
    return max(shares) if shares else 0.0


def describe_sample(sample):
    """Return a one-line description of a sample."""
    return "%s: %s" % (sample.batch, sample.dose)


def group_by_batch(samples):
    """Return a dict from batch to the list of samples with that batch."""
    groups = {}
    for x in samples:
        groups.setdefault(x.batch, []).append(x)
    return groups

